export declare const Voice: VoiceApi;

/**
 * Voice API — place outbound voice calls from inside a job, webhook, or
 * skill tool. The platform allocates a LiveKit room, dials the target,
 * seeds the LuaVoice with the dev's `context`, and returns a session id
 * the dev can use to read the transcript later (when the LuaVoice has
 * `persistTranscript: true`).
 */
export declare interface VoiceApi {
    /**
     * Place an outbound voice call.
     *
     * @example
     * ```typescript
     * // Recovery flow — call abandoned-cart user with order context
     * await Voice.call({
     *   to: '+15551234567',
     *   voice: 'support-line',
     *   context: { reason: 'recovery', orderId: 'O-123' },
     * });
     * ```
     *
     * @example
     * ```typescript
     * // Web flow — return a join URL the dev's frontend opens
     * const { joinUrl, sessionId } = await Voice.call({
     *   to: { kind: 'web', returnToken: true },
     *   context: { customer: 'Acme Co' },
     * });
     * ```
     */
    call(input: VoiceDispatchInput): Promise<VoiceDispatchOutput>;
}

/**
 * The dev's input to `Voice.call`. `voice` is optional — when omitted,
 * the calling agent's bound voice (the first entry in `subAgent.voices`)
 * is used.
 */
declare interface VoiceDispatchInput {
    /** Where to dial. PSTN string is sugar; objects allow `meet` / `web`. */
    to: VoiceDispatchTarget;
    /**
     * LuaVoice id or name to use. Optional — defaults to the calling
     * agent's primary voice (first entry of `subAgent.voices`). The voice
     * MUST belong to the same agent; cross-agent voice rental is not
     * supported in this iteration.
     */
    voice?: string;
    /**
     * Free-form context object. The worker seeds this into the LuaVoice's
     * initial `ChatContext` so the LLM sees it on the first turn — no
     * extra round-trip needed for "look up the order I'm calling about."
     *
     * Stored verbatim and surfaced to the dev's hooks via
     * `ctx.session.userdata.dispatchContext`. Must be JSON-serializable.
     */
    context?: Record<string, unknown>;
    /**
     * Optional thread id suffix. When present, LuaVoice sandbox APIs
     * (`User.get`, `Data.get`, etc.) scope to this thread. Defaults to
     * `voice:<sessionId>` so each call gets isolated storage by default.
     */
    threadId?: string;
    /**
     * Optional channel kind override. The dispatcher infers from `to.kind`
     * by default — use this to label web flows that aren't browser-based
     * (e.g. iOS SDK) so analytics/billing can split the bucket.
     */
    channel?: 'phone' | 'meeting' | 'whatsapp' | 'webchat' | 'unknown';
}

/**
 * Result returned to the dev. Never throws on a placed-but-unanswered
 * call — that's a runtime outcome, not a dispatch failure. Errors during
 * dispatch (no matching voice, exhausted quota, target invalid) surface
 * as a thrown error from `Voice.call`.
 */
declare interface VoiceDispatchOutput {
    /**
     * Worker-local session id for this call. Use as the key for
     * `Data.get('call:<sessionId>')` when LuaVoice has
     * `persistTranscript: true`.
     */
    sessionId: string;
    /** LiveKit room name the call landed in. */
    roomName: string;
    /**
     * Provider-specific call id. For `phone`, the LiveKit SIP participant
     * sid; for `meet`, the lua-recall bot id; for `web`, undefined.
     */
    callId?: string;
    /**
     * Browser-attachable join URL for `kind: 'web'` with `returnToken: true`.
     * Undefined for phone/meet.
     */
    joinUrl?: string;
}

/**
 * Wire types for outbound voice dispatch (`Voice.call` / `this.voice.call`).
 *
 * The dev's payload flows through three boundaries:
 *   1. lua-cli sandbox `Voice.call(input)` — public surface devs see.
 *   2. lua-api `POST /voice/dispatch` — auth + ownership + quota gate.
 *   3. lua-livekit dispatcher — allocates a LiveKit room and dials the
 *      target appropriately (SIP participant for phone, recall bot for
 *      meeting, raw join token for web).
 *
 * Keeping a single canonical input/output shape avoids drift across the
 * three layers; everything except auth headers passes through verbatim.
 */
/**
 * Where to place the call. PSTN is the common case so a bare E.164 string
 * is accepted as sugar for `{ kind: 'phone', number }`. The `meet` and
 * `web` variants use a tagged object so future kinds (e.g. WebRTC SDK
 * peer) can be added without breaking the union.
 */
declare type VoiceDispatchTarget = 
/** Sugar for `{ kind: 'phone', number }`. Must be E.164 (`+15551234567`). */
string | {
    kind: 'phone';
    /** E.164 number to dial. */
    number: string;
    /**
     * Optional outbound caller-id. When omitted, the worker picks an
     * org-owned phone number that the trunk routes outbound from.
     */
    callerId?: string;
} | {
    kind: 'meet';
    /** Meeting URL (Google Meet / Zoom / etc.). */
    url: string;
} | {
    kind: 'web';
    /**
     * If true, response carries `joinUrl` — the dev's client opens it
     * to attach to the room. If false, the room is allocated but no
     * join token is returned (useful for server-side warm-up).
     */
    returnToken?: boolean;
};

/**
 * Webhook request information from channel integrations.
 * Contains the raw webhook payload from the channel provider.
 */
export declare interface WebhookRequest {
    /** The raw, unmodified webhook payload from the channel provider */
    payload: any;
}

